// Pure note shaping. No I/O.

export type Note = {
  id: string;
  teamId: string;
  authorId: string;
  title: string;
  body: string;
  version: number;
  createdAt: string;
  updatedAt: string;
};

export type NoteRow = {
  seq: number;
  id: string;
  team_id: string;
  author_id: string;
  title: string;
  body: string;
  version: number;
  created_at: string;
  updated_at: string;
  deleted_at: string | null;
};

export type NewNoteInput = { id: string; teamId: string; authorId: string; title: string; body: string };

/** Row -> API shape. Lists exactly the Note schema fields (additionalProperties: false). */
export function toNote(row: NoteRow): Note {
  return {
    id: row.id,
    teamId: row.team_id,
    authorId: row.author_id,
    title: row.title,
    body: row.body,
    version: row.version,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** A brand-new note: version 1, both timestamps equal to `now` (ISO-8601 UTC, ms precision). */
export function newNoteFields(input: NewNoteInput, now: Date): Note {
  const ts = now.toISOString();
  return { ...input, version: 1, createdAt: ts, updatedAt: ts };
}
// Pure input validation. No I/O. Parses unknown JSON once into trusted values.

export type FieldError = { field: string; message: string };
export type Result<T> = { ok: true; value: T } | { ok: false; errors: FieldError[] };

export type NoteCreate = { title: string; body: string };
export type NotePatch = { title?: string; body?: string };

export const TITLE_MAX = 200;
export const BODY_MAX = 100000;

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

function checkTitle(v: unknown, errors: FieldError[]): string | undefined {
  if (typeof v !== 'string') {
    errors.push({ field: 'title', message: 'must be a string' });
    return undefined;
  }
  const t = v.trim();
  if (t.length < 1 || t.length > TITLE_MAX) {
    errors.push({ field: 'title', message: `must be 1-${TITLE_MAX} characters after trimming` });
    return undefined;
  }
  return t;
}

function checkBody(v: unknown, errors: FieldError[]): string | undefined {
  if (typeof v !== 'string') {
    errors.push({ field: 'body', message: 'must be a string' });
    return undefined;
  }
  if (v.length > BODY_MAX) {
    errors.push({ field: 'body', message: `must be at most ${BODY_MAX} characters` });
    return undefined;
  }
  return v;
}

function unknownFields(input: Record<string, unknown>, allowed: string[], errors: FieldError[]): void {
  for (const k of Object.keys(input)) {
    if (!allowed.includes(k)) errors.push({ field: k, message: 'unknown field' });
  }
}

const notAnObject: FieldError = { field: '$', message: 'request body must be a JSON object' };

export function validateCreate(input: unknown): Result<NoteCreate> {
  if (!isPlainObject(input)) return { ok: false, errors: [notAnObject] };
  const errors: FieldError[] = [];
  unknownFields(input, ['title', 'body'], errors);
  const title = 'title' in input ? checkTitle(input.title, errors) : (errors.push({ field: 'title', message: 'is required' }), undefined);
  const body = 'body' in input ? checkBody(input.body, errors) : '';
  if (errors.length > 0 || title === undefined || body === undefined) return { ok: false, errors };
  return { ok: true, value: { title, body } };
}

export function validatePatch(input: unknown): Result<NotePatch> {
  if (!isPlainObject(input)) return { ok: false, errors: [notAnObject] };
  const errors: FieldError[] = [];
  unknownFields(input, ['title', 'body'], errors);
  const value: NotePatch = {};
  if ('title' in input) { const t = checkTitle(input.title, errors); if (t !== undefined) value.title = t; }
  if ('body' in input) { const b = checkBody(input.body, errors); if (b !== undefined) value.body = b; }
  if (Object.keys(input).length === 0) errors.push({ field: '$', message: 'at least one field is required' });
  return errors.length > 0 ? { ok: false, errors } : { ok: true, value };
}
-- Team Notes: the SQLite schema shared by every backend.
-- Timestamps are ISO-8601 UTC strings with millisecond precision, generated by the application.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS users (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  token_hash  TEXT NOT NULL UNIQUE          -- sha256 hex of the bearer token; plaintext is never stored
);

CREATE TABLE IF NOT EXISTS teams (
  id        TEXT PRIMARY KEY,
  name      TEXT NOT NULL,
  owner_id  TEXT NOT NULL REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS memberships (
  team_id  TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role     TEXT NOT NULL CHECK (role IN ('owner', 'member')),
  PRIMARY KEY (team_id, user_id)
);

CREATE TABLE IF NOT EXISTS notes (
  seq         INTEGER PRIMARY KEY AUTOINCREMENT, -- internal ordering key for keyset pagination
  id          TEXT NOT NULL UNIQUE,              -- public UUID
  team_id     TEXT NOT NULL REFERENCES teams(id),
  author_id   TEXT NOT NULL REFERENCES users(id),
  title       TEXT NOT NULL,
  body        TEXT NOT NULL DEFAULT '',
  version     INTEGER NOT NULL DEFAULT 1,        -- optimistic concurrency; exposed as ETag
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  deleted_at  TEXT                               -- soft delete (Tier 2)
);
CREATE INDEX IF NOT EXISTS notes_team_seq ON notes(team_id, seq);

